import sys

def calculate_efficiency_gap():
    P, D = map(int, input().split())
    total_votes = 0
    wasted_a = 0
    wasted_b = 0

    for _ in range(P):
        district, votes_a, votes_b = map(int, input().split())
        total_votes += votes_a + votes_b

        if votes_a > votes_b:
            wasted_a += votes_a - (votes_a + votes_b) // 2
            wasted_b += votes_b
        else:
            wasted_b += votes_b - (votes_a + votes_b) // 2
            wasted_a += votes_a

    for district in range(1, D + 1):
        votes_a = votes_b = 0
        for _ in range(P):
            d, a, b = map(int, input().split())
            if d == district:
                votes_a += a
                votes_b += b

        if votes_a > votes_b:
            print('A', votes_a - (votes_a + votes_b) // 2, votes_b)
        else:
            print('B', votes_a, votes_b - (votes_a + votes_b) // 2)

    efficiency_gap = abs(wasted_a - wasted_b) / total_votes
    print(f"{efficiency_gap:.10f}")

if __name__ == "__main__":
    calculate_efficiency_gap()
